local function _bxor(a, b)
    local r, bit = 0, 1
    while a > 0 or b > 0 do
        local aa = a % 2
        local bb = b % 2
        if aa ~= bb then r = r + bit end
        a = math.floor(a / 2)
        b = math.floor(b / 2)
        bit = bit * 2
    end
    return r
end

local function _b64decode(s)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local out = {}
    local n = 0
    local acc = 0
    for i = 1, #s do
        local c = s:sub(i, i)
        if c ~= "=" then
            local v = alphabet:find(c, 1, true)
            if v then
                v = v - 1
                acc = acc * 64 + v
                n = n + 6
                while n >= 8 do
                    n = n - 8
                    local byte = math.floor(acc / (2 ^ n)) % 256
                    out[#out + 1] = string.char(byte)
                    acc = acc % (2 ^ n)
                end
            end
        end
    end
    return table.concat(out)
end

local _encoded = table.concat(_B64)
