local _out = {}
for i = 1, #_raw do
    local p = i
    local v = string.byte(_raw, i)
    local k2 = (167 + p * 19 + (p % 251) * 7) % 256
    local x = (v - k2) % 256
    local k1 = (109 + p * 37 + math.floor(p / 256) * 11) % 256
    _out[i] = string.char(_bxor(x, k1))
end
_raw = nil

local _source = table.concat(_out)
_out = nil
local _fn, _err = loadstring(_source)
_source = nil
if not _fn then
    error(_err)
end
